/*
 * tests/parity/gemm_vp_pro_emit.c -- C-side emitter of the gemm_vp_pro parity family
 * (the register-staged global prefetch body of the universal GEMM; see
 * _gemm_vp_common.py). Builds the specs of gemm_vp_pro_emit.py (same order, same
 * values) through the C API so run_diff.py can byte-compare the two engines.
 * The case rows are generated: `python gemm_vp_pro_emit.py --c-cases`.
 *
 * the screened prologue set on the register-staged body: every recipe (h16 out_f32, f32 cvt / x3 / x4 / x6 / x9) x body (modes 3 / 4, main-loop levers, unroll) x complex form (cplx_b, conj) x batched x geometry, plus wide_addr, split modes, lds_swizzle_l, split_at load and modes 1 / 2.
 */
